/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: stub, mount, section
 *   Constants: tracksPath
 * Tests
 *   - an Album page lists its members in Album order with metadata, states and links to their own catalog pages
 *   - the section rereads on a later page Refresh, but a remount after an earlier one reads only once
 *   - a failed member read retries from the section and from the page Refresh, and other kinds never read members
 *   - the strict member schema refuses private fields, unknown states and misnumbered or repeated members
 * @end-catalog */

import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { AdminCatalogPage } from './AdminCatalogPage';
import AdminRouter from './AdminRouter';
import { CatalogAlbumTracks as CatalogAlbumTracksSection } from './CatalogAlbumTracks';
import { catalogAlbumTracksSchema, type CatalogAlbumTracks } from './catalogAlbumTracksApi';
import { json, session, viewer } from './adminFixtures.testSupport';
import { albumId, catalogAlbum, catalogAlbumTracks } from './catalogReviewFixtures.testSupport';

const tracksPath = `/api/admin/v1/catalog/album/${albumId}/tracks`;
/** Answers the Album page reads; `tracks` answers each member read in turn, repeating its last answer. */
function stub(tracks: Array<CatalogAlbumTracks | Response>) {
  const reads: string[] = [];
  vi.stubGlobal('fetch', vi.fn(async (path: string) => {
    reads.push(path);
    if (path.endsWith('/tracks')) { const next = tracks.length > 1 ? tracks.shift()! : tracks[0]; return next instanceof Response ? next : json(next); }
    if (path.endsWith('/cover-operations')) return json({ items: [] });
    if (path.endsWith('/motion-preview')) return json({ code: 'ADMIN_MOTION_PREVIEW_DISABLED' }, 404);
    if (path.includes('/catalog/artist/')) return json({ item: { ...catalogAlbum(), kind: 'artist', fields: { name: 'Synthetic artist', bio: '', birthDate: null, musicBrainzId: null } } });
    if (path.includes('/catalog/audioTrack/')) return json({ item: { ...catalogAlbum(), kind: 'audioTrack', id: '333333333333333333333333', fields: { ...catalogAlbum().fields, title: 'Synthetic first track', discNumber: 1, trackNumber: 1 } } });
    return json({ item: catalogAlbum() });
  }));
  return reads;
}
function mount(element: React.ReactNode, path = '/') {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
  render(<QueryClientProvider client={client}><MemoryRouter initialEntries={[path]}>{element}</MemoryRouter></QueryClientProvider>);
}
const section = async () => screen.findByRole('region', { name: 'Tracks' });
beforeEach(() => { adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }); adminWorkspace.select('admin'); });
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); vi.restoreAllMocks(); });

test('an Album page lists its members in Album order with metadata, states and links to their own catalog pages', async () => {
  const reads = stub([catalogAlbumTracks()]);
  mount(<AdminRouter />, `/admin/catalog/album/${albumId}`);
  const tracks = await section();
  expect(within(tracks).getByRole('heading', { level: 2, name: 'Tracks' })).toBeVisible();
  const rows = await within(tracks).findAllByRole('listitem');
  // The explicit role keeps list semantics that VoiceOver drops from a list without markers.
  expect(within(tracks).getByRole('list')).toHaveAttribute('role', 'list');
  expect(rows.map(row => row.textContent)).toEqual([
    '1Synthetic first trackDisc number 1 · Track number 1 · 03:05 · Audio',
    '2Synthetic second track1:02:03 · VideoHidden',
    '3Synthetic unfinished uploadDisc number 2 · Track number 3 · AudioUpload unfinished',
    '4Missing MediaTrack recordc2c2c2c2c2c2c2c2c2c2c2c2'
  ]);
  expect(within(rows[0]).getByRole('link', { name: 'Synthetic first track' })).toHaveAttribute('href', '/admin/catalog/audioTrack/333333333333333333333333');
  expect(within(rows[1]).getByRole('link', { name: 'Synthetic second track' })).toHaveAttribute('href', '/admin/catalog/audioTrack/444444444444444444444444');
  // Only a ready MediaTrack has a catalog page; the others are not links.
  expect(within(rows[2]).queryByRole('link')).not.toBeInTheDocument(); expect(within(rows[3]).queryByRole('link')).not.toBeInTheDocument();
  expect(within(tracks).getAllByRole('link')).toHaveLength(2);
  // Read-only: nothing in the section edits or reorders members.
  expect(within(tracks).queryByRole('button')).not.toBeInTheDocument(); expect(within(tracks).queryByRole('textbox')).not.toBeInTheDocument();
  expect(reads.filter(path => path.endsWith(tracksPath))).toHaveLength(1);
  fireEvent.click(within(rows[0]).getByRole('link', { name: 'Synthetic first track' }));
  expect(await screen.findByRole('textbox', { name: 'Title' })).toHaveValue('Synthetic first track');
  expect(screen.queryByRole('region', { name: 'Tracks' })).not.toBeInTheDocument();
});

test.each([
  ['an empty Album', { ...catalogAlbumTracks(), tracks: [] }, ['This Album has no tracks.']],
  ['an older Album without a stored order', { ...catalogAlbumTracks(), order: 'legacyAlbumLinks' as const },
    ['Read-only. This older Album stores no track order, so its linked tracks are listed by title, as listeners receive them; open a track to edit it.']],
  ['an oversized Album', { ...catalogAlbumTracks(), truncated: true }, ['Only the first 4 tracks are listed.']],
  ['an Album whose stored membership needs repair', { ...catalogAlbumTracks(), tracks: [], skipped: 2 },
    ['This Album has no tracks.', '2 stored track entries are malformed or repeated and need repair.']],
  ['an Album with a member linked to another Album', { ...catalogAlbumTracks(), tracks: catalogAlbumTracks().tracks.map(track => track.position === 1 ? { ...track, linkedElsewhere: true } : track) },
    ['Not linked to this Album']]
])('%s explains its member list', async (_name, value, copy) => {
  stub([value]);
  mount(<AdminCatalogPage kind="album" id={albumId} />);
  const tracks = await section();
  for (const text of copy) expect(await within(tracks).findByText(text)).toBeVisible();
  expect(within(tracks).queryAllByRole('listitem')).toHaveLength(value.tracks.length);
  // One ordering note: a legacy Album's replaces the declared order's, which would be false for it.
  expect(within(tracks).getAllByText(/^Read-only/)).toHaveLength(1);
});

test('the section rereads on a later page Refresh, but a remount after an earlier one reads only once', async () => {
  const reads = stub([catalogAlbumTracks()]), client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  client.setQueryData(['browser-session'], session);
  const memberReads = () => reads.filter(path => path.endsWith(tracksPath)).length;
  const view = (refresh: number | null) => <QueryClientProvider client={client}><MemoryRouter>
    {refresh !== null && <CatalogAlbumTracksSection id={albumId} refresh={refresh} />}</MemoryRouter></QueryClientProvider>;
  const { rerender } = render(view(2));
  expect(await within(await section()).findAllByRole('listitem')).toHaveLength(4);
  expect(memberReads()).toBe(1);
  // A remount while the earlier list is still cached, as after a cover removal, rereads once rather than twice.
  rerender(view(null)); rerender(view(2));
  await waitFor(() => expect(memberReads()).toBe(2));
  expect(await within(await section()).findAllByRole('listitem')).toHaveLength(4);
  expect(memberReads()).toBe(2);
  rerender(view(3));
  await waitFor(() => expect(memberReads()).toBe(3));
});

test('a failed member read retries from the section and from the page Refresh, and other kinds never read members', async () => {
  const reads = stub([json({ code: 'ADMIN_CATALOG_UNAVAILABLE' }, 503), catalogAlbumTracks()]);
  mount(<AdminCatalogPage kind="album" id={albumId} />);
  const tracks = await section();
  const alert = await within(tracks).findByRole('alert');
  expect(alert).toHaveTextContent('Tracks could not be loaded. Try again.');
  fireEvent.click(within(alert).getByRole('button', { name: 'Try again' }));
  expect(await within(tracks).findAllByRole('listitem')).toHaveLength(4);
  expect(within(tracks).queryByRole('alert')).not.toBeInTheDocument();
  fireEvent.click(screen.getAllByRole('button', { name: 'Refresh status' })[0]);
  await waitFor(() => expect(reads.filter(path => path.endsWith(tracksPath))).toHaveLength(3));
  cleanup();
  const artistReads = stub([catalogAlbumTracks()]);
  mount(<AdminCatalogPage kind="artist" id={albumId} />);
  expect(await screen.findByRole('textbox', { name: 'Name' })).toHaveValue('Synthetic artist');
  expect(screen.queryByRole('region', { name: 'Tracks' })).not.toBeInTheDocument();
  expect(artistReads.some(path => path.endsWith('/tracks'))).toBe(false);
});

test('the strict member schema refuses private fields, unknown states and misnumbered or repeated members', () => {
  expect(catalogAlbumTracksSchema.safeParse(catalogAlbumTracks()).success).toBe(true);
  const [first, second] = catalogAlbumTracks().tracks;
  for (const tracks of [
    [{ ...first, s3Key: 'audio/private' }], [{ ...first, mediaUrl: '/private' }], [{ ...first, musicBrainzId: '11111111-2222-4333-8444-555555555555' }],
    [{ ...first, state: 'deleted' }], [{ ...first, duration: 'soon' }], [{ ...first, linkedElsewhere: 'yes' }], [{ ...first, linkedElsewhere: undefined }], [{ ...second, position: 2 }], [first, { ...second, position: 3 }], [first, { ...second, id: first.id }],
    [{ position: 1, id: first.id, state: 'missing', title: 'Leaked' }]
  ]) expect(catalogAlbumTracksSchema.safeParse({ ...catalogAlbumTracks(), tracks }).success, JSON.stringify(tracks)).toBe(false);
  expect(catalogAlbumTracksSchema.safeParse({ ...catalogAlbumTracks(), revision: `cr_${'a'.repeat(43)}` }).success).toBe(false);
  for (const skipped of [-1, 1.5, 501, undefined]) expect(catalogAlbumTracksSchema.safeParse({ ...catalogAlbumTracks(), skipped }).success, String(skipped)).toBe(false);
});
